    if limit < 0 {
        return None;
    }
    let n = keys.len() as isize;
    if n == 0 {
        return Some(vec![]);
    }
    let mut result: Vec<usize> = Vec::new();
    let mut i: usize = 0;
    while i < n {
        if result.len() as isize >= limit {
            break;
        }
        if keys[i] == keys[0] {
            result.push(i);
            i += 1;
        } else {
            i += 1;
        }
    }
    Some(result)
}

